// Multiple top-level package-private classes bundled for a runnable demo.
package com.bank.tokencache;

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TtlCacheDemo {

    private static final Logger log = Logger.getLogger(TtlCacheDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TtlCache cache = new TtlCache();

        // t=100: write auth code valid for 60 time units (expires at 160), version 1.
        cache.put("AUTH-SAV2001", "CODE-7788", 60, 100);
        log.info(() -> "get @t=120 -> " + cache.get("AUTH-SAV2001", 120));  // valid

        // t=150: customer refreshes BEFORE old expiry → new value, expiry 210, version 2.
        cache.put("AUTH-SAV2001", "CODE-9900", 60, 150);

        // Stale cleanup scheduled for old expiry 160 runs now; must NOT delete version 2.
        cache.proactiveCleanup(165);
        log.info(() -> "get @t=170 -> " + cache.get("AUTH-SAV2001", 170));  // still CODE-9900

        // t=215: now the version-2 entry is truly expired.
        log.info(() -> "get @t=215 -> " + cache.get("AUTH-SAV2001", 215));  // miss
    }
}

