class ExpiryRecord {
    final String key;
    final long expiresAt;
    final long version;

    ExpiryRecord(String key, long expiresAt, long version) {
        this.key = key;
        this.expiresAt = expiresAt;
        this.version = version;
    }
}

// ─── Would be in TtlCache.java in a real project ───
class TtlCache {

    private static final Logger log = Logger.getLogger(TtlCache.class.getName());

    private final Map<String, Entry> store = new HashMap<>();
    private final Map<String, Long> versionCounter = new HashMap<>();
    // Min-heap ordered by expiry time for proactive cleanup.
    private final PriorityQueue<ExpiryRecord> expiryHeap =
            new PriorityQueue<>((a, b) -> Long.compare(a.expiresAt, b.expiresAt));

    // O(log n) due to heap push; the map part is O(1).
    void put(String key, String value, long ttl, long now) {
        long version = versionCounter.merge(key, 1L, Long::sum);
        long expiresAt = now + ttl;
        store.put(key, new Entry(value, expiresAt, version));
        expiryHeap.offer(new ExpiryRecord(key, expiresAt, version));
        log.fine(() -> "put " + key + "=" + value + " expiresAt=" + expiresAt + " v=" + version);
    }

    // O(1) lazy expiry: valid only while now < expiresAt.
    String get(String key, long now) {
        Entry e = store.get(key);
        if (e == null) {
            return null;
        }
        if (now < e.expiresAt) {
            return e.value;
        }
        store.remove(key);                       // lazy delete of expired entry
        log.fine(() -> "lazy-expired " + key + " @now=" + now);
        return null;
    }

    // O(log n) per popped record: delete only if version still matches (skip stale records).
    void proactiveCleanup(long now) {
        while (!expiryHeap.isEmpty() && expiryHeap.peek().expiresAt <= now) {
            ExpiryRecord rec = expiryHeap.poll();
            Entry e = store.get(rec.key);
            if (e != null && e.version == rec.version) {
                store.remove(rec.key);
                log.info(() -> "cleanup removed " + rec.key + " v=" + rec.version);
            } else {
                log.info(() -> "cleanup SKIP stale record " + rec.key + " v=" + rec.version
                        + " (live v=" + (e == null ? "none" : e.version) + ")");
            }
        }
    }
}

